INSERT INTO book_text (book_id, page_index, text, blocks, source)
SELECT b.id, v.page_index, v.text, NULL::jsonb, $$manifest_txt_v1$$
  FROM (VALUES
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 0, $$My little brother sleeps very late. I wake early, because I am a big girl!$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 1, $$I am the one who opens the window to let the sun shine in.$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 2, $$"O my darling daughter, you are my sweetheart," says Mama.$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 3, $$Mama said, "My daughter, don't forget to brush your teeth. " And I answered, "You don't have to remind me mama. I am a big girl. "$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 4, $$The water is cold, but that is okay. I am a big girl, so I wash my face.$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 5, $$I wash myself. I don't need any help.$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 6, $$After bathing, I greet Grandpa and Auntie, and wish them a good day.$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 7, $$Then I dress myself. “I’m big now Mama,” I say.$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 8, $$I can put on my own shoes.$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 9, $$My little brother and I talk all the way to school. I take good care of him because I am a big girl.$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 10, $$At school, I try hard to do very good work.$$),
    ('4cacdc53-49b4-4a10-a6da-763a521a1002', 11, $$I do all these good things every day. But even though I am a big girl, I still love to play and play!$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 0, $$This is Cat.$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 1, $$Cat and Dog live in a house. The house has a door. The house has a roof.$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 2, $$Cat and Dog have a ball. The ball is red and blue and green.$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 3, $$Cat and Dog play with the ball. Cat throws the ball to Dog. Dog catches the ball. Dog throws the ball to Cat. Cat catches the ball.$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 4, $$Then Cat throws the ball very high. Oh! Oh!$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 5, $$The ball is on the roof. The ball is on the roof of the house.$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 6, $$Cat and Dog can see the ball. Cat and Dog cannot get to the ball.$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 7, $$Cat and Dog cry. Then Elephant comes by.$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 8, $$Elephant is big. Elephant can see the ball. Elephant can get to the ball. Elephant gets the ball from the roof.$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 9, $$Elephant gives the ball to Cat and Dog. Cat and Dog smile. Elephant smiles. Cat and Dog and Elephant smile.$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 10, $$Cat and Dog and Elephant play with the ball.$$),
    ('4e1a12a3-5bd4-415b-a697-a1fe7824ce1c', 11, $$Bye-bye Cat. Bye-bye Dog. Bye-bye Elephant$$),
    ('4eb2ee6c-9c10-469c-9f4f-7b68fa1a3ac3', 0, $$Baboon and Crocodile were the best of friends. They played together. They ate together. They did everything together.$$),
    ('4eb2ee6c-9c10-469c-9f4f-7b68fa1a3ac3', 1, $$But one day, Crocodile got so sick that he was almost dead. When he saw that his sickness was getting worse, Crocodile went to the nyabezi who said, “If you want to get better, you have to eat baboon meat. ”$$),
    ('4eb2ee6c-9c10-469c-9f4f-7b68fa1a3ac3', 2, $$When he heard this, Crocodile was sad. But there was no other option to heal himself except to eat his friend the baboon.$$),
    ('4eb2ee6c-9c10-469c-9f4f-7b68fa1a3ac3', 3, $$When Baboon went to see his friend, Crocodile put him on his back and took him out to the deepest part of the river.$$),
    ('4eb2ee6c-9c10-469c-9f4f-7b68fa1a3ac3', 4, $$Crocodile said, “The nyabezi told me that if I am to be healed I must eat you, my friend. ”$$),
    ('4eb2ee6c-9c10-469c-9f4f-7b68fa1a3ac3', 5, $$Then, Baboon replied, “No, my friend. Don’t eat me. I’m too small. Wait a minute and I’ll call my grandfather. He’s bigger than me. Eat him and you’ll be full. ”$$),
    ('4eb2ee6c-9c10-469c-9f4f-7b68fa1a3ac3', 6, $$Then Crocodile said, “Where is this grandfather of yours? ” Baboon said, “He’s in that tree, over on that island. ” Crocodile said, “Go get him so that I may eat him. ”$$),
    ('4eb2ee6c-9c10-469c-9f4f-7b68fa1a3ac3', 7, $$Baboon jumped off Crocodile’s back and ran straight up the tree and stayed there. Crocodile waited and waited. But he didn’t see any sign of Baboon. And that was the end of their friendship.$$),
    ('4ffbc553-75ba-4499-84c4-3de5c923a3a5', 0, $$Everytime I finish my hot, hot bath, My wet body feels so cool, cool cool. Who makes that happen? Vayu the Wind!$$),
    ('4ffbc553-75ba-4499-84c4-3de5c923a3a5', 1, $$The milk in my cup is too hot, too hot. But soon it is ready for me to gulp. Who makes that happen? Vayu the Wind!$$),
    ('4ffbc553-75ba-4499-84c4-3de5c923a3a5', 2, $$The window curtains flutter and gently brush my face. Who makes it happen? Vayu, the Wind!$$),
    ('4ffbc553-75ba-4499-84c4-3de5c923a3a5', 3, $$A bolt of lightning far away. Black clouds moving my way. Who makes that happen? Vayu, the Wind!$$),
    ('4ffbc553-75ba-4499-84c4-3de5c923a3a5', 4, $$Branches sway and leaves tremble. Flowers gently fall. Who did it all? Vayu, the Wind!$$),
    ('4ffbc553-75ba-4499-84c4-3de5c923a3a5', 5, $$Far from the house, we are playing, Yet, I can smell the sweets mother is preparing. Who makes it happen? Vayu, the Wind!$$),
    ('4ffbc553-75ba-4499-84c4-3de5c923a3a5', 6, $$A glass tumbler on a window sill, Crashes on the ground. Thank God, I was not around. Who played this mischief? Of course, it was Vayu, the Wind!$$),
    ('4ffbc553-75ba-4499-84c4-3de5c923a3a5', 7, $$A whistle blows. A train rolls in. I cannot see, but I hear its din. Who makes that happen? Vayu, the Wind!$$),
    ('4ffbc553-75ba-4499-84c4-3de5c923a3a5', 8, $$Cannot be seen. Cannot be heard. Does all the work Without a word. Who can it be?$$),
    ('4ffbc553-75ba-4499-84c4-3de5c923a3a5', 9, $$Of course! The wind! Vayu, the wind!$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 0, $$I have a friend. She lives in my house.$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 1, $$When I am happy, so is she.$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 2, $$When I cry, she cries too.$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 3, $$But I cannot hear her voice. My friend lives inside the mirror.$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 4, $$“Come out,” I tell her, “we will play. ” She does not come out.$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 5, $$I am not happy. I go to sleep.$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 6, $$She comes out of the mirror in my sleep! And we have fun.$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 7, $$We play, we run, we shout and scream together.$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 8, $$When I talk to her, she also talks to me.$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 9, $$In the morning, my friend will go back into the mirror.$$),
    ('518623fc-2bf1-4d68-8b76-33e0a7c8f421', 10, $$But I don't mind at all. We will play again in my dreams!$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 0, $$Princess Amiya was born on the 16th of January, 2012. She was such a pretty baby that everyone in the village came to see her.$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 1, $$She loves plants and enjoys eating fruits.$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 2, $$$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 3, $$$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 4, $$One of the Princess's favourite thing to do is going to tea parties. She is truly a princess.$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 5, $$She is loved by everyone.$$),
