    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 10, $$$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 11, $$She has a lot of love for animals. The princess takes care of all the animals around her.$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 12, $$$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 13, $$$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 14, $$$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 15, $$She wants to be a Princess Doctor so she will take care of all the sick people and animals.$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 16, $$$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 17, $$$$),
    ('537842d8-96e1-4fb5-a31d-deb1092e3bb8', 18, $$Her favourite time of year is the Christmas season. She enjoys getting presents!$$),
