    ('9455894a-b5b1-475e-a06f-0ea256897a07', 6, $$I kick my red ball.$$),
    ('9455894a-b5b1-475e-a06f-0ea256897a07', 7, $$I kick my red ball hard!$$),
    ('9455894a-b5b1-475e-a06f-0ea256897a07', 8, $$Where?$$),
    ('9455894a-b5b1-475e-a06f-0ea256897a07', 9, $$Where is my ball?$$),
    ('9455894a-b5b1-475e-a06f-0ea256897a07', 10, $$Where is my ball now?$$),
    ('9455894a-b5b1-475e-a06f-0ea256897a07', 11, $$Where is my red ball now?$$),
    ('9455894a-b5b1-475e-a06f-0ea256897a07', 12, $$It is up.$$),
    ('9455894a-b5b1-475e-a06f-0ea256897a07', 13, $$It is high up in the sky.$$),
    ('9455894a-b5b1-475e-a06f-0ea256897a07', 14, $$It is high up in the sky. It is over the moon. It is gone!$$),
